const MapAlaska = ({ element, active, highlighted, width, onClick, onChange }) => {
  return (
    <ElementWrapper
      element={element}
      onClick={onClick}
      onChange={onChange}
      maxWidth={width}
      active={active}
      highlighted={highlighted}
      resizeHandles={['e']}
      editable
      fit
    >
      <MapAlaskaContent element={element} />
    </ElementWrapper>
  );
};

export const MapAlaskaPresent = ({ element }) => {
  return <MapAlaskaContent element={element} />;
};

